namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int OnSubtotal(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + OrderSizePoints(subtotalCents), CeilingPoints);

        return subtotalCents * points / 100;
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };

    private static int OrderSizePoints(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3
    };
}
E
